/// <summary>
/// class <c>METTelemetryPOConfirmationInfoEvent</c> is used to log error event whenever purchase order confirmation info event.
/// </summary>
internal final class METTelemetryPOConfirmationInfoEvent extends ISMTelemetryBase
{
}

Method.Source:
/// <summary>
/// Initialize the class <c>METTelemetryPOConfirmationInfoEvent</c>
/// </summary>
/// <returns> Instance of class <c>METTelemetryPOConfirmationInfoEvent</c> </returns>
public static METTelemetryPOConfirmationInfoEvent construct()
{
    return new METTelemetryPOConfirmationInfoEvent();
}

/// <summary>
/// Run confirmation journal error event
/// </summary>
/// <param name = "_purchId"> purchase id </param>
/// <param name = "_error"> error message </param>
public static void runTelemetryEvent(PurchId _purchId)
{
    METTelemetryPOConfirmationInfoEvent pOConfirmationEvent = METTelemetryPOConfirmationInfoEvent::construct();

    pOConfirmationEvent.addRunTimePropertyToAppinsights(_purchId);

    pOConfirmationEvent.processEvent(METTelemetryEventNames::POConfirmedEvent);
}

protected void new()
{
    super();

    this.eventId = METTelemetryEventNames::POConfirmedEvent;
}

/// <summary>
/// if the log level is set to information it will log the request and response data as wekk as there is an error
/// </summary>
/// <returns> a boolean value </returns>
protected boolean shouldLogEvent()
{
    return true;
}

/// <summary>
/// Add runtime telemetry property to application insights.
/// </summary>
/// <param name = "_purchId"> purchId </c> </param>
public void addRunTimePropertyToAppinsights(PurchId _purchId)
{
    PurchTable purchTable = PurchTable::find(_purchId);

    this.addRuntimeProperty('PurchaseOrderId', purchTable.PurchId);
    this.addRuntimeProperty('warehouseId' ,purchTable.InventLocationId);
    this.addRuntimeProperty('VendorOrderReference', purchTable.VendorRef);
    this.addRuntimeProperty('VendorAccount', purchTable.OrderAccount);
    this.addRuntimeProperty('VendorAccount', purchTable.InventLocationId);
    this.addRuntimeProperty('VendorOrderReference', purchTable.VendorRef);
    this.addRuntimeProperty('BuyerGroup', purchTable.ItemBuyerGroupId);
}
